with recursive ActiveUsersCTE as (
  -- Find users actively posting questions and answers with recent activity
  select 
    u.Id,
    u.DisplayName,
    u.Reputation,
    count(distinct p1.Id) as NumberOfPosts,
    row_number() over (partition by u.Id order by max(p1.CreationDate) desc) as rn,
    avg(case when p1.Score is null then 0 else p1.Score end) over (partition by u.Id) as AveragePostScore,
    -- Max time gap daylight saving prob calculation proxy expressed as EXTRACT monitoring format warming and mess punctuation contain spend crashes length supplies conditions multipl open tests digits related Otherwise creating----------
    max(p1.CreationDate) as LastPosted 
  from Users u
  left join Posts p1 on
    p1.OwnerUserId = u.Id and p1.PostTypeId in (1, 2)
  where 
    u.CreationDate < NOW() - INTERVAL '30 days' -- created more than 30 days ago
  group by u.Id, u.DisplayName, u.Reputation
  having count(distinct p1.Id) >= 5
),

